package br.com.strumlab.songbooks;

import java.util.*;
import java.time.OffsetDateTime;
import java.nio.charset.StandardCharsets;
import java.security.*;
import org.springframework.beans.factory.annotation.Value;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;
import tools.jackson.databind.ObjectMapper;
import br.com.strumlab.songs.*;
import static br.com.strumlab.songbooks.BookModels.*;

@Service
public class BookService {
    public static final String RENDERER="pdfkit-a4-v1";
    private final JdbcTemplate jdbc;private final ObjectMapper json;private final UUID owner;
    public BookService(JdbcTemplate jdbc,ObjectMapper json,@Value("${strumlab.workspace-id:00000000-0000-4000-8000-000000000001}")UUID owner){this.jdbc=jdbc;this.json=json;this.owner=owner;}
    private Summary map(java.sql.ResultSet rs)throws java.sql.SQLException{return new Summary(rs.getObject("id",UUID.class),rs.getString("title"),rs.getString("subtitle"),rs.getBoolean("archived"),rs.getLong("version"),rs.getInt("item_count"),rs.getObject("updated_at",OffsetDateTime.class));}
    private Summary owned(UUID id,boolean lock){var rows=jdbc.query("SELECT b.id,b.title,b.subtitle,b.archived,b.version,b.updated_at, (SELECT COUNT(*) FROM songbook_item WHERE songbook_id=b.id) AS item_count FROM songbook b WHERE b.id=? AND owner_id=?"+(lock?" FOR UPDATE":""),(rs,n)->map(rs),id,owner);if(rows.isEmpty())throw new SongProblem(404,"Cancioneiro não encontrado.");return rows.getFirst();}
    private Summary check(UUID id,Long version,boolean allowArchived){var b=owned(id,true);if(version==null)throw new SongProblem(422,"Informe a versão do cancioneiro.");if(version!=b.version())throw new SongProblem(409,"O cancioneiro mudou em outra aba. Recarregue para continuar.");if(!allowArchived&&b.archived())throw new SongProblem(409,"Reabra o cancioneiro antes de alterar.");return b;}
    private void bump(UUID id){jdbc.update("UPDATE songbook SET version=version+1,updated_at=CURRENT_TIMESTAMP WHERE id=? AND owner_id=?",id,owner);}
    private Config config(UUID id){return jdbc.queryForObject("SELECT * FROM songbook WHERE id=? AND owner_id=?",(rs,n)->new Config(rs.getString("title"),rs.getString("subtitle"),rs.getString("organizer"),json.readValue(rs.getString("cover_json"),Cover.class),json.readValue(rs.getString("layout_json"),Layout.class)),id,owner);}
    public Page list(String q,String status,int offset){if(q.length()>200||offset<0||!Set.of("active","archived","all").contains(status))throw new SongProblem(422,"Filtro inválido.");String where=" WHERE owner_id=? AND title ILIKE ? ESCAPE '\\'";var args=new ArrayList<Object>(List.of(owner,"%"+q.replace("\\","\\\\").replace("%","\\%").replace("_","\\_")+"%"));if(!status.equals("all")){where+=" AND archived=?";args.add(status.equals("archived"));}int total=jdbc.queryForObject("SELECT COUNT(*) FROM songbook"+where,Integer.class,args.toArray());args.add(offset);var items=jdbc.query("SELECT b.id,b.title,b.subtitle,b.archived,b.version,b.updated_at, (SELECT COUNT(*) FROM songbook_item WHERE songbook_id=b.id) AS item_count FROM songbook b"+where+" ORDER BY updated_at DESC,id LIMIT 50 OFFSET ?",(rs,n)->map(rs),args.toArray());return new Page(items,total);}
    @Transactional(readOnly=true,isolation=org.springframework.transaction.annotation.Isolation.REPEATABLE_READ)
    public Detail detail(UUID id){var book=owned(id,false);return new Detail(book,config(id),items(id),exports(id));}
    private List<Item> items(UUID id){return jdbc.query("SELECT i.*,r.revision_no,r.content_json,s.current_revision_id,s.status FROM songbook_item i JOIN song_revision r ON r.id=i.song_revision_id JOIN song s ON s.id=i.song_id WHERE i.songbook_id=? AND s.owner_id=? ORDER BY i.position",(rs,n)->new Item(rs.getObject("id",UUID.class),rs.getObject("song_id",UUID.class),rs.getObject("song_revision_id",UUID.class),rs.getInt("revision_no"),rs.getInt("position"),rs.getString("notes"),json.readValue(rs.getString("content_json"),SongContent.class),rs.getObject("current_revision_id",UUID.class),rs.getString("status").equals("archived")),id,owner);}
    @Transactional public Detail create(Config config){BookValidation.config(config);UUID id=UUID.randomUUID();jdbc.update("INSERT INTO songbook(id,owner_id,title,subtitle,organizer,cover_json,layout_json) VALUES (?,?,?,?,?,?::jsonb,?::jsonb)",id,owner,config.title(),config.subtitle(),config.organizer(),json.writeValueAsString(config.cover()),json.writeValueAsString(config.layout()));return detail(id);}
    @Transactional public Detail update(UUID id,Long version,Config config){check(id,version,false);BookValidation.config(config);jdbc.update("UPDATE songbook SET title=?,subtitle=?,organizer=?,cover_json=?::jsonb,layout_json=?::jsonb WHERE id=? AND owner_id=?",config.title(),config.subtitle(),config.organizer(),json.writeValueAsString(config.cover()),json.writeValueAsString(config.layout()),id,owner);bump(id);return detail(id);}
    @Transactional public Detail archive(UUID id,Long version,boolean archived){check(id,version,true);jdbc.update("UPDATE songbook SET archived=? WHERE id=? AND owner_id=?",archived,id,owner);bump(id);return detail(id);}
    private void revisionOwned(UUID songId,UUID revisionId,boolean adding){var rows=jdbc.queryForList("SELECT s.status FROM song s JOIN song_revision r ON r.song_id=s.id WHERE s.id=? AND r.id=? AND s.owner_id=?",songId,revisionId,owner);if(rows.isEmpty())throw new SongProblem(404,"Música/revisão não encontrada na sua biblioteca.");if(adding&&rows.getFirst().get("status").equals("archived"))throw new SongProblem(409,"Reabra a música antes de adicioná-la.");}
    @Transactional public Detail add(UUID id,Long version,UUID songId,UUID revisionId,boolean duplicate){var book=check(id,version,false);revisionOwned(songId,revisionId,true);if(book.itemCount()>=200)throw new SongProblem(422,"O limite local é 200 itens por livro.");if(!duplicate&&jdbc.queryForObject("SELECT COUNT(*) FROM songbook_item WHERE songbook_id=? AND song_id=?",Integer.class,id,songId)>0)throw new SongProblem(409,"Esta música já está no livro. Use Duplicar item para repetir explicitamente.");jdbc.update("INSERT INTO songbook_item(id,songbook_id,song_id,song_revision_id,position) VALUES (?,?,?,?,?)",UUID.randomUUID(),id,songId,revisionId,book.itemCount());bump(id);return detail(id);}
    @Transactional public Detail reorder(UUID id,Long version,List<UUID> order){check(id,version,false);var actual=items(id).stream().map(Item::id).toList();if(order==null||order.size()!=actual.size()||new HashSet<>(order).size()!=order.size()||!new HashSet<>(actual).equals(new HashSet<>(order)))throw new SongProblem(422,"A ordem precisa conter exatamente os itens atuais, sem repetição.");for(int position=0;position<order.size();position++)jdbc.update("UPDATE songbook_item SET position=? WHERE id=? AND songbook_id=?",position,order.get(position),id);bump(id);return detail(id);}
    @Transactional public Detail remove(UUID id,Long version,UUID itemId){check(id,version,false);var actual=items(id);if(actual.stream().noneMatch(i->i.id().equals(itemId)))throw new SongProblem(404,"Item não encontrado.");jdbc.update("DELETE FROM songbook_item WHERE id=? AND songbook_id=?",itemId,id);int position=0;for(var item:actual)if(!item.id().equals(itemId))jdbc.update("UPDATE songbook_item SET position=? WHERE id=? AND songbook_id=?",position++,item.id(),id);bump(id);return detail(id);}
    @Transactional public Detail updateItem(UUID id,Long version,UUID itemId,UUID revisionId,String notes){check(id,version,false);var item=items(id).stream().filter(i->i.id().equals(itemId)).findFirst().orElseThrow(()->new SongProblem(404,"Item não encontrado."));revisionOwned(item.songId(),revisionId,false);if(notes==null||notes.length()>1000)throw new SongProblem(422,"Nota deve ter até 1000 caracteres.");jdbc.update("UPDATE songbook_item SET song_revision_id=?,notes=? WHERE id=? AND songbook_id=?",revisionId,notes,itemId,id);bump(id);return detail(id);}
    private Export exportMap(java.sql.ResultSet rs)throws java.sql.SQLException{String index=rs.getString("page_index_json");return new Export(rs.getObject("id",UUID.class),rs.getObject("songbook_id",UUID.class),rs.getLong("book_version"),rs.getString("manifest_hash"),rs.getString("renderer_version"),rs.getString("status"),rs.getObject("page_count",Integer.class),index==null?List.of():Arrays.asList(json.readValue(index,PageIndex[].class)),rs.getString("pdf_sha256"),rs.getString("error_code"),rs.getObject("created_at",OffsetDateTime.class));}
    private List<Export> exports(UUID id){return jdbc.query("SELECT id,songbook_id,book_version,manifest_hash,renderer_version,status,page_count,page_index_json,pdf_sha256,error_code,created_at FROM songbook_export WHERE songbook_id=? ORDER BY created_at DESC LIMIT 50",(rs,n)->exportMap(rs),id);}
    public Export export(UUID bookId,UUID exportId){owned(bookId,false);var values=jdbc.query("SELECT id,songbook_id,book_version,manifest_hash,renderer_version,status,page_count,page_index_json,pdf_sha256,error_code,created_at FROM songbook_export WHERE songbook_id=? AND id=?",(rs,n)->exportMap(rs),bookId,exportId);if(values.isEmpty())throw new SongProblem(404,"Exportação não encontrada.");return values.getFirst();}
    private static String hash(byte[] value){try{return HexFormat.of().formatHex(MessageDigest.getInstance("SHA-256").digest(value));}catch(NoSuchAlgorithmException e){throw new IllegalStateException(e);}}
    @Transactional public RenderClaim begin(UUID id,Long version){var book=check(id,version,false);var config=config(id);var items=items(id);if(items.isEmpty())throw new SongProblem(422,"Adicione uma revisão de música antes de gerar a prévia.");long characters=items.stream().mapToLong(i->json.writeValueAsString(i.content()).length()).sum();if(characters>750000)throw new SongProblem(422,"O livro excede o limite local de conteúdo. Divida o repertório em livros menores.");var manifest=new Manifest(1,RENDERER,id,book.version(),config.title(),config.subtitle(),config.organizer(),config.cover(),config.layout(),items.stream().map(i->new ManifestItem(i.id(),i.songId(),i.revisionId(),i.revisionNo(),i.content(),i.notes())).toList());String serialized=json.writeValueAsString(manifest);String hash=hash(serialized.getBytes(StandardCharsets.UTF_8));var existing=jdbc.queryForList("SELECT id,status,lease_started_at FROM songbook_export WHERE songbook_id=? AND manifest_hash=? FOR UPDATE",id,hash);UUID exportId,lease=UUID.randomUUID();
        if(existing.isEmpty()){exportId=UUID.randomUUID();jdbc.update("INSERT INTO songbook_export(id,songbook_id,book_version,manifest_json,manifest_hash,renderer_version,status,lease_token) VALUES (?,?,?,?::jsonb,?,?,'pending',?)",exportId,id,book.version(),serialized,hash,RENDERER,lease);}
        else {var row=existing.getFirst();exportId=(UUID)row.get("id");var status=(String)row.get("status");var started=((java.sql.Timestamp)row.get("lease_started_at")).toInstant();if(status.equals("completed")||(status.equals("pending")&&started.isAfter(java.time.Instant.now().minusSeconds(90))))return new RenderClaim(export(id,exportId),manifest,null);jdbc.update("UPDATE songbook_export SET status='pending',lease_token=?,lease_started_at=CURRENT_TIMESTAMP,error_code=NULL WHERE id=?",lease,exportId);}
        return new RenderClaim(export(id,exportId),manifest,lease);
    }
    @Transactional public Export complete(UUID bookId,UUID exportId,Result result){owned(bookId,false);var rows=jdbc.queryForList("SELECT manifest_json::text AS manifest,manifest_hash,lease_token,status FROM songbook_export WHERE id=? AND songbook_id=? FOR UPDATE",exportId,bookId);if(rows.isEmpty())throw new SongProblem(404,"Exportação não encontrada.");var row=rows.getFirst();if(!Objects.equals(row.get("lease_token"),result.leaseToken())||!Objects.equals(row.get("manifest_hash"),result.manifestHash()))throw new SongProblem(409,"A tentativa de exportação não é mais atual.");if(row.get("status").equals("completed"))return export(bookId,exportId);if(!row.get("status").equals("pending"))throw new SongProblem(409,"A exportação não está em processamento.");var manifest=json.readValue((String)row.get("manifest"),Manifest.class);if(result.pdfBase64()==null||result.pdfBase64().length()>23000000||result.pageCount()<1||result.pageCount()>500||result.pageIndex()==null||result.pageIndex().size()!=manifest.items().size())throw new SongProblem(422,"Resultado de PDF inválido.");byte[] pdf;try{pdf=Base64.getDecoder().decode(result.pdfBase64());}catch(IllegalArgumentException e){throw new SongProblem(422,"PDF inválido.");}if(pdf.length>16777216||pdf.length<20||!new String(pdf,0,5,StandardCharsets.US_ASCII).equals("%PDF-")||!new String(pdf,Math.max(0,pdf.length-1024),Math.min(1024,pdf.length),StandardCharsets.US_ASCII).contains("%%EOF"))throw new SongProblem(422,"PDF inválido ou muito grande.");int previous=0;for(int n=0;n<manifest.items().size();n++){var item=manifest.items().get(n);var index=result.pageIndex().get(n);if(index==null||!item.itemId().equals(index.itemId())||!item.content().title().equals(index.title())||item.revisionNo()!=index.revisionNo()||index.page()<1||index.page()>result.pageCount()||index.page()<previous)throw new SongProblem(422,"Índice do PDF incompatível com o manifesto.");previous=index.page();}jdbc.update("UPDATE songbook_export SET status='completed',pdf_bytes=?,pdf_sha256=?,page_count=?,page_index_json=?::jsonb,error_code=NULL WHERE id=?",pdf,hash(pdf),result.pageCount(),json.writeValueAsString(result.pageIndex()),exportId);return export(bookId,exportId);}
    @Transactional public Export fail(UUID bookId,UUID exportId,UUID lease){owned(bookId,false);var rows=jdbc.queryForList("SELECT status,lease_token FROM songbook_export WHERE id=? AND songbook_id=? FOR UPDATE",exportId,bookId);if(rows.isEmpty())throw new SongProblem(404,"Exportação não encontrada.");var row=rows.getFirst();if(!row.get("status").equals("completed")&&Objects.equals(row.get("lease_token"),lease))jdbc.update("UPDATE songbook_export SET status='failed',error_code='render_failed' WHERE id=?",exportId);return export(bookId,exportId);}
    public byte[] pdf(UUID bookId,UUID exportId){var value=export(bookId,exportId);if(!value.status().equals("completed"))throw new SongProblem(409,"O PDF ainda não está disponível.");return jdbc.queryForObject("SELECT pdf_bytes FROM songbook_export WHERE id=?",byte[].class,exportId);}
}
